  } else {
    add(Math.floor(amount / 50), 50);
    const fives = Math.floor((amount % 50) / 5);
    add(fives, 5);
    // Bytecode uses the five-count % 5, rather than the remaining value % 5.
    add(fives % 5, 1);
  }
  return values;
}

export function spawnPickups(
